(5733680, 834029, 91915, '<td valign="top">Beautiful capture. Nice light on the trees and moody sky.<br/>One suggestion would be to crop out a bit more of the underexposed foreground.</td>', 'Beautiful capture. Nice light on the trees and moody sky.One suggestion would be to crop out a bit more of the underexposed foreground.', '2009-11-19 14:07:01.000000', NULL, 1),
(5733699, 833394, 108580, '<td valign="top">Now this is a decent child photo. Eyes, focus, B+W. Black shadow on her right neckline detracts a bit. Would love this to ribbon. I am not a fave of child photo''s, but this is how it should be done when it''s done.</td>', 'Now this is a decent child photo. Eyes, focus, B+W. Black shadow on her right neckline detracts a bit. Would love this to ribbon. I am not a fave of child photo''s, but this is how it should be done when it''s done.', '2009-11-19 14:16:52.000000', NULL, 1),
(5733787, 834108, 98977, '<td valign="top">Really neat macro! Love the B/W as well nice work!</td>', 'Really neat macro! Love the B/W as well nice work!', '2009-11-19 15:35:18.000000', NULL, 1),
(5733832, 834146, 45631, '<td valign="top">This is an interesting image but viewing it in the context of being a centered composition, I find that the part that draws my eyes is the lighting in the leaves and this is making it more of a split composition.  The darkness has not worked for this subject IMO.</td>', 'This is an interesting image but viewing it in the context of being a centered composition, I find that the part that draws my eyes is the lighting in the leaves and this is making it more of a split composition.  The darkness has not worked for this subject IMO.', '2009-11-19 16:19:59.000000', NULL, 1),
