(5734004, 834058, 51538, '<td valign="top">"<a href="//www.youtube.com/watch?v=2CFSyHBVxDQ&amp;feature=related" rel="nofollow" target="_blank">Are you my mummy?</a>"<br/>-- Doctor Who episode</td>', '"Are you my mummy?"-- Doctor Who episode', '2009-11-19 18:02:32.000000', NULL, 1),
(5734074, 833394, 108982, '<td valign="top">the title tells the story.  I usually don''t fall for the allure of the young but you really caught a beautiful child here.  The bare hint of a smile without a smile works really well.  The tight focus really give a nice soft lower line and brings out the child''s eyes.  B&amp;W was an excellent choice; I think that this picture would have lost impact in color.  Nice and a clear 10.</td>', 'the title tells the story.  I usually don''t fall for the allure of the young but you really caught a beautiful child here.  The bare hint of a smile without a smile works really well.  The tight focus really give a nice soft lower line and brings out the child''s eyes.  B&W was an excellent choice; I think that this picture would have lost impact in color.  Nice and a clear 10.', '2009-11-19 18:48:39.000000', NULL, 1),
(5734099, 833819, 104378, '<td valign="top">everything about this pictures is just captivating</td>', 'everything about this pictures is just captivating', '2009-11-19 19:11:55.000000', NULL, 1),
