INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5734204, 833932, 21714, '<td valign="top">Nice catch. The composition is excellent. Focus on the wire mesh - I don''t know if it''s a bad thing since it''s the angle of the wires and the birds legs that interest me most (I know most would say focus on the bird''s eye). I guess processing can be a bit better.</td>', 'Nice catch. The composition is excellent. Focus on the wire mesh - I don''t know if it''s a bad thing since it''s the angle of the wires and the birds legs that interest me most (I know most would say focus on the bird''s eye). I guess processing can be a bit better.', '2009-11-19 20:44:04.000000', NULL, 1),
(5734208, 833513, 21714, '<td valign="top">Ah! Magic!</td>', 'Ah! Magic!', '2009-11-19 20:46:20.000000', NULL, 1),
(5734213, 833791, 21714, '<td valign="top">Cool shot. Really like it. <br/>** white thin outline is annoying me! (no points deducted though)</td>', 'Cool shot. Really like it. ** white thin outline is annoying me! (no points deducted though)', '2009-11-19 20:49:59.000000', NULL, 1),
(5734223, 834203, 21714, '<td valign="top">The ground is almost like an angry sky or stormy sea (yeah, for some reason I want the ground to be anything but). At the same time it''s quite relaxing too. Many to things to love about this photograph.</td>', 'The ground is almost like an angry sky or stormy sea (yeah, for some reason I want the ground to be anything but). At the same time it''s quite relaxing too. Many to things to love about this photograph.', '2009-11-19 20:56:00.000000', NULL, 1),
(5734229, 833632, 21714, '<td valign="top">Can justify a big dinner.</td>', 'Can justify a big dinner.', '2009-11-19 20:58:05.000000', NULL, 1),
(5734234, 834248, 21714, '<td valign="top">That hand there creating a black palm print immediately grabs me. It''s pretty close to becoming one of the most interesting images I have seen in a while. But, I think you need to spend a bit more time on this one and I think it would be worth trying out different crops too. <br/>You could have cropped it a bit closer. I am not liking the way the ankles are chopped off. It''s the palm that grabs me and I think that''s what you have used too as the centre (but you could make it dead centre) and maybe you could try to put even more emphasis on that. <br/> <br/>Just some thoughts since I think it''s a great click.</td>', 'That hand there creating a black palm print immediately grabs me. It''s pretty close to becoming one of the most interesting images I have seen in a while. But, I think you need to spend a bit more time on this one and I think it would be worth trying out different crops too. You could have cropped it a bit closer. I am not liking the way the ankles are chopped off. It''s the palm that grabs me and I think that''s what you have used too as the centre (but you could make it dead centre) and maybe you could try to put even more emphasis on that.  Just some thoughts since I think it''s a great click.', '2009-11-19 21:05:01.000000', NULL, 1),
(5734238, 833909, 21714, '<td valign="top">This is beautifully done. Excecution to presentation - Good enough for a 10. Love the precision.</td>', 'This is beautifully done. Excecution to presentation - Good enough for a 10. Love the precision.', '2009-11-19 21:07:59.000000', NULL, 1),
