(5734758, 834050, 42256, '<td valign="top">Beautiful focus, right at the tip of the petals...Gave it a 7 because of the dried petals that are visible towards the right top corner and bottom right.. A square crop might have worked better imo.</td>', 'Beautiful focus, right at the tip of the petals...Gave it a 7 because of the dried petals that are visible towards the right top corner and bottom right.. A square crop might have worked better imo.', '2009-11-20 10:07:19.000000', NULL, 1),
(5734759, 833907, 42256, '<td valign="top">Great wide angle symmetrical shot! Love the control of light.. without really blowing out any details! 7</td>', 'Great wide angle symmetrical shot! Love the control of light.. without really blowing out any details! 7', '2009-11-20 10:08:31.000000', NULL, 1),
(5734781, 833746, 105457, '<td valign="top">Like the composition and the conversion for sepia, but it was a pity for the blown whites. 7</td>', 'Like the composition and the conversion for sepia, but it was a pity for the blown whites. 7', '2009-11-20 10:45:00.000000', NULL, 1),
