(5734794, 834095, 105457, '<td valign="top">Good macro.</td>', 'Good macro.', '2009-11-20 10:51:39.000000', NULL, 1),
(5734795, 834029, 105457, '<td valign="top">Hum, it''s puzzling the way the light appeared on the hill, it looks like you lightpainted the whole scene :)<br/>I like the tones and the subject. 8</td>', 'Hum, it''s puzzling the way the light appeared on the hill, it looks like you lightpainted the whole scene :)I like the tones and the subject. 8', '2009-11-20 10:52:29.000000', NULL, 1),
