(5734850, 834199, 105457, '<td valign="top">I like the bokeh of this photo.</td>', 'I like the bokeh of this photo.', '2009-11-20 11:48:45.000000', NULL, 1),
(5734854, 833632, 105457, '<td valign="top">Well, this is unusual. A perfect entry for the <a href="//www.dpchallenge.com/challenge_results.php?CHALLENGE_ID=1122" rel="nofollow" target="_blank">Symmetry III</a>challenge, but also adapts well to this challenge. Nice leading lines.</td>', 'Well, this is unusual. A perfect entry for the Symmetry IIIchallenge, but also adapts well to this challenge. Nice leading lines.', '2009-11-20 11:50:01.000000', NULL, 1),
(5734858, 834036, 105457, '<td valign="top">Nice picture! Could be better if it was a bit brighter, it''s underexposed.</td>', 'Nice picture! Could be better if it was a bit brighter, it''s underexposed.', '2009-11-20 11:51:46.000000', NULL, 1),
(5734859, 834120, 105457, '<td valign="top">Good job on the lighting, was it lightpainted?<br/>A little dark in the middle, but otherwise a very good entry.</td>', 'Good job on the lighting, was it lightpainted?A little dark in the middle, but otherwise a very good entry.', '2009-11-20 11:52:24.000000', NULL, 1),
(5734860, 834202, 105457, '<td valign="top">Nice title, very good job on the PP of the skin. A little high key, but enough to have all details and colours in.</td>', 'Nice title, very good job on the PP of the skin. A little high key, but enough to have all details and colours in.', '2009-11-20 11:53:17.000000', NULL, 1),
