(5734867, 834236, 105457, '<td valign="top">Nice idea, and could be so much better performed (later at night, driving away from the car, etc).</td>', 'Nice idea, and could be so much better performed (later at night, driving away from the car, etc).', '2009-11-20 12:00:21.000000', NULL, 1),
(5734885, 833492, 106543, '<td valign="top">Great concept!</td>', 'Great concept!', '2009-11-20 12:12:33.000000', NULL, 1),
(5734894, 833969, 45631, '<td valign="top">This image is not very strong to meet the challenge.  Yes, the subject is centered but a square crop removing the distracting elements of no interest at the bottom and leaving some blue sky above may have helped.  Composition doesn''t work as you don''t get a full view of the building.  Work on these things for your next entry.</td>', 'This image is not very strong to meet the challenge.  Yes, the subject is centered but a square crop removing the distracting elements of no interest at the bottom and leaving some blue sky above may have helped.  Composition doesn''t work as you don''t get a full view of the building.  Work on these things for your next entry.', '2009-11-20 12:20:34.000000', NULL, 1),
(5734927, 834145, 108392, '<td valign="top">wonderfull.</td>', 'wonderfull.', '2009-11-20 12:48:31.000000', NULL, 1),
