(5734951, 834149, 42256, '<td valign="top">Great simple subject, nice composition and lighting.  8</td>', 'Great simple subject, nice composition and lighting.  8', '2009-11-20 13:02:12.000000', NULL, 1),
(5734954, 833909, 42256, '<td valign="top">You rocked it for the third time, although your first 2 were better.. my favorite is still from the first challenge! 9</td>', 'You rocked it for the third time, although your first 2 were better.. my favorite is still from the first challenge! 9', '2009-11-20 13:03:38.000000', NULL, 1),
(5734955, 834185, 99256, '<td valign="top">I like the use of fisheye here.  Very interesting shot.</td>', 'I like the use of fisheye here.  Very interesting shot.', '2009-11-20 13:04:33.000000', NULL, 1),
(5734956, 834172, 42256, '<td valign="top">Beautiful lighting, great textures of the floor.  I am not liking the cut marks on the cutting board! 7</td>', 'Beautiful lighting, great textures of the floor.  I am not liking the cut marks on the cutting board! 7', '2009-11-20 13:06:19.000000', NULL, 1),
(5734957, 834282, 99256, '<td valign="top">I like this.  I would have liked it even more if his eye was more in focus instead of his side (but would it still fit the challenge?)  I dunno, good shot either way.</td>', 'I like this.  I would have liked it even more if his eye was more in focus instead of his side (but would it still fit the challenge?)  I dunno, good shot either way.', '2009-11-20 13:06:33.000000', NULL, 1),
(5734959, 833712, 99256, '<td valign="top">Nice shot and interesting subject.  I can''t put my finger on why but it just doesn''t really stand out to me.  If I get some more time I''ll come back and look at it some more and try to figure out why that is. (No vote unless I come back)</td>', 'Nice shot and interesting subject.  I can''t put my finger on why but it just doesn''t really stand out to me.  If I get some more time I''ll come back and look at it some more and try to figure out why that is. (No vote unless I come back)', '2009-11-20 13:06:39.000000', NULL, 1),
(5734962, 834237, 99256, '<td valign="top">Nice shot but theres nothing that really keeps my interest.  Also the focus is a little soft.</td>', 'Nice shot but theres nothing that really keeps my interest.  Also the focus is a little soft.', '2009-11-20 13:09:00.000000', NULL, 1),
(5734963, 833798, 99256, '<td valign="top">I like this one a lot.  Nice use of color.</td>', 'I like this one a lot.  Nice use of color.', '2009-11-20 13:09:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5734965, 834087, 99256, '<td valign="top">Nice car.  I''m being drawn to the grill and the headlights and not the center of the frame (which is in the middle of the hood.  Pretty good shot though.  I hope the DNMC brats out there don''t hurt you.</td>', 'Nice car.  I''m being drawn to the grill and the headlights and not the center of the frame (which is in the middle of the hood.  Pretty good shot though.  I hope the DNMC brats out there don''t hurt you.', '2009-11-20 13:13:17.000000', NULL, 1),
(5734986, 833291, 83313, '<td valign="top">A fun shot, I like the idea. Can I borrow the tape when you are done with it?</td>', 'A fun shot, I like the idea. Can I borrow the tape when you are done with it?', '2009-11-20 13:35:37.000000', NULL, 1),
(5734989, 833660, 83313, '<td valign="top">I always thought vacuum tubes looked like cutaway drawings of what was inside a fictional rocketship.</td>', 'I always thought vacuum tubes looked like cutaway drawings of what was inside a fictional rocketship.', '2009-11-20 13:37:06.000000', NULL, 1),
(5734994, 833633, 83313, '<td valign="top">A fun shot. Not sure if all the negative space at the top is doing much for it, but that''s probably a personal preference thing, as it was clearly intentional. Otherwise, I like this.</td>', 'A fun shot. Not sure if all the negative space at the top is doing much for it, but that''s probably a personal preference thing, as it was clearly intentional. Otherwise, I like this.', '2009-11-20 13:40:55.000000', NULL, 1),
(5734997, 833679, 83313, '<td valign="top">Perhaps she is just another girl, but as this image clearly shows, the vibes are centered around her. This would not be the same party if she left. Did you get her number?</td>', 'Perhaps she is just another girl, but as this image clearly shows, the vibes are centered around her. This would not be the same party if she left. Did you get her number?', '2009-11-20 13:43:49.000000', NULL, 1),
(5735001, 833997, 83313, '<td valign="top">Comes off somewhat flat looking to me. I think some appropriate adjustments (such as curves, saturation, contrast, sharpening) could give it a bit more snap.</td>', 'Comes off somewhat flat looking to me. I think some appropriate adjustments (such as curves, saturation, contrast, sharpening) could give it a bit more snap.', '2009-11-20 13:46:29.000000', NULL, 1),
(5735006, 834004, 83313, '<td valign="top">At a 30k file size, JPEG compression is the major thing that is taking away sharpness and clarity from this image. Always use the least compression you can get away with and still come in under the challenge limit. You had 10 times the file size to play with then what you used. If you were to try a re-edit, I think it will make a noticeable difference.</td>', 'At a 30k file size, JPEG compression is the major thing that is taking away sharpness and clarity from this image. Always use the least compression you can get away with and still come in under the challenge limit. You had 10 times the file size to play with then what you used. If you were to try a re-edit, I think it will make a noticeable difference.', '2009-11-20 13:49:17.000000', NULL, 1),
(5735008, 833930, 83313, '<td valign="top">The large border works well for this. Looks like a print hanging on my wall.</td>', 'The large border works well for this. Looks like a print hanging on my wall.', '2009-11-20 13:50:15.000000', NULL, 1),
(5735054, 834130, 42256, '<td valign="top">Its great lighting, white background is amazing with the black dress.  I would have voted it higher if the eyes were a little more visible! 7</td>', 'Its great lighting, white background is amazing with the black dress.  I would have voted it higher if the eyes were a little more visible! 7', '2009-11-20 14:19:01.000000', NULL, 1),
(5735056, 833791, 42256, '<td valign="top">Nice sharp focus and beautiful reflection..works really well for the challenge! 8</td>', 'Nice sharp focus and beautiful reflection..works really well for the challenge! 8', '2009-11-20 14:19:48.000000', NULL, 1),
(5735059, 834267, 42256, '<td valign="top">Nice light on the heron and fairly sharp.  Lack of soft bokeh is adding distraction and the rocks in the front are not doing much. 7</td>', 'Nice light on the heron and fairly sharp.  Lack of soft bokeh is adding distraction and the rocks in the front are not doing much. 7', '2009-11-20 14:21:40.000000', NULL, 1),
(5735062, 834148, 42256, '<td valign="top">for some strange reason I like this shot, don''t know why but it has a character to it.. although I am sure you are getting hammered by dpc voters! Good luck! 7</td>', 'for some strange reason I like this shot, don''t know why but it has a character to it.. although I am sure you are getting hammered by dpc voters! Good luck! 7', '2009-11-20 14:23:05.000000', NULL, 1),
(5735066, 834035, 42256, '<td valign="top">Really nice sharp focus and great editing.  Gave it a 7, would have been higher if my eyes were not getting drawn to the light on the left where I can see the messy hair.  A closer crop might have worked better!</td>', 'Really nice sharp focus and great editing.  Gave it a 7, would have been higher if my eyes were not getting drawn to the light on the left where I can see the messy hair.  A closer crop might have worked better!', '2009-11-20 14:24:29.000000', NULL, 1),
(5735067, 834231, 42256, '<td valign="top">this is beautiful and simple,  I really like the editing and duotones.  Gave it a 7 because I feel the background texture is overpowering the leaf.</td>', 'this is beautiful and simple,  I really like the editing and duotones.  Gave it a 7 because I feel the background texture is overpowering the leaf.', '2009-11-20 14:26:07.000000', NULL, 1),
(5735070, 834030, 42256, '<td valign="top">I really like the B&amp;W editing of this shot... those blown highlights to a certain extend work well, but I feel a stop lower with an off camera flash behind the opened door would have given this shot a lot more character! 7</td>', 'I really like the B&W editing of this shot... those blown highlights to a certain extend work well, but I feel a stop lower with an off camera flash behind the opened door would have given this shot a lot more character! 7', '2009-11-20 14:28:35.000000', NULL, 1),
(5735076, 833685, 42256, '<td valign="top">Great composition and nice use of leading lines.  6 .. IMO colors are oversaturated and the shot is lacking sharpness.. those two fixes and I would have rated it higher</td>', 'Great composition and nice use of leading lines.  6 .. IMO colors are oversaturated and the shot is lacking sharpness.. those two fixes and I would have rated it higher', '2009-11-20 14:36:28.000000', NULL, 1),
(5735079, 833633, 42256, '<td valign="top">Nice pose and lighting 6 .. i don''t think the extra background on the top is adding any interest to the picture, except that it makes this picture fit the challenge. IMO what would have worked better is a closer crop so that the bubblegum becomes the center of the frame .. i would have given it a 10 with that crop!</td>', 'Nice pose and lighting 6 .. i don''t think the extra background on the top is adding any interest to the picture, except that it makes this picture fit the challenge. IMO what would have worked better is a closer crop so that the bubblegum becomes the center of the frame .. i would have given it a 10 with that crop!', '2009-11-20 14:38:23.000000', NULL, 1),
(5735081, 833569, 42256, '<td valign="top">Nice symmetry (although slightly tilted) and light on the building.  B&amp;W processing works well...6</td>', 'Nice symmetry (although slightly tilted) and light on the building.  B&W processing works well...6', '2009-11-20 14:39:43.000000', NULL, 1),
(5735082, 834287, 42256, '<td valign="top">Great composition and nice colors and lighting..Gave it a 7 .. seeing beetles on flower reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=40718" rel="nofollow" target="_blank">DrAchoo</a>''s shots and I am looking for sharper beetles (hence the lower score)</td>', 'Great composition and nice colors and lighting..Gave it a 7 .. seeing beetles on flower reminds me of  DrAchoo''s shots and I am looking for sharper beetles (hence the lower score)', '2009-11-20 14:41:44.000000', NULL, 1),
(5735083, 833094, 42256, '<td valign="top">Good effort and nice lighting  .. gave it a 6 because the shot is missing the drama .. using a colored background and without that extra drop on top would have worked better!</td>', 'Good effort and nice lighting  .. gave it a 6 because the shot is missing the drama .. using a colored background and without that extra drop on top would have worked better!', '2009-11-20 14:43:30.000000', NULL, 1),
(5735098, 833690, 110041, '<td valign="top">Looks a little out of focus</td>', 'Looks a little out of focus', '2009-11-20 15:21:59.000000', NULL, 1),
(5735099, 833932, 110041, '<td valign="top">Nice capture</td>', 'Nice capture', '2009-11-20 15:23:32.000000', NULL, 1),
(5735185, 833704, 105457, '<td valign="top">Nice one <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=97814" rel="nofollow" target="_blank">jomerner</a>:)<br/> <br/>It''s so balanced, and so smooth. Must have been hard to get it to stand still though.<br/>Also because of the lighting you were able to darken your reflection on the marble, that would be visible on the shot otherwise.<br/> <br/>Congratulations, 9</td>', 'Nice one  jomerner:) It''s so balanced, and so smooth. Must have been hard to get it to stand still though.Also because of the lighting you were able to darken your reflection on the marble, that would be visible on the shot otherwise. Congratulations, 9', '2009-11-20 17:12:45.000000', NULL, 1),
(5735200, 834027, 108982, '<td valign="top">this is a stunning capture.  you were either 1. very lucky to being the right place at the right time.  2. very patient and spent a lot of time setting this up.  OR  3. know the right people to help set this up.  in any case it is one of the best in flight photos I have ever seen.  wow a very well deserved 10.  would love to see a "how I got the shot" tutorial.</td>', 'this is a stunning capture.  you were either 1. very lucky to being the right place at the right time.  2. very patient and spent a lot of time setting this up.  OR  3. know the right people to help set this up.  in any case it is one of the best in flight photos I have ever seen.  wow a very well deserved 10.  would love to see a "how I got the shot" tutorial.', '2009-11-20 17:26:44.000000', NULL, 1),
(5735201, 834210, 108982, '<td valign="top">nice photo, i appreciate the simplicity and lack of make up or "extras".  This would have garnered a ten if you could have gotten rid of the umbrella flash in her stunning eyes  9</td>', 'nice photo, i appreciate the simplicity and lack of make up or "extras".  This would have garnered a ten if you could have gotten rid of the umbrella flash in her stunning eyes  9', '2009-11-20 17:28:06.000000', NULL, 1),
(5735202, 833781, 108982, '<td valign="top">Great character portrait.  Clear expression in the eyes, no special effects just a really good photo.  love the very sharp focus to gather detail..a 9 in this group.</td>', 'Great character portrait.  Clear expression in the eyes, no special effects just a really good photo.  love the very sharp focus to gather detail..a 9 in this group.', '2009-11-20 17:29:09.000000', NULL, 1),
(5735206, 833633, 47470, '<td valign="top">I would have cropped a little closer (the hand makes her seem too self-conscious) and placed the bubble in the very center.  You can get bigger bubbles if you don''t use real bubble gum, but a balloon instead!</td>', 'I would have cropped a little closer (the hand makes her seem too self-conscious) and placed the bubble in the very center.  You can get bigger bubbles if you don''t use real bubble gum, but a balloon instead!', '2009-11-20 17:30:14.000000', NULL, 1),
(5735208, 833819, 108982, '<td valign="top">nice capture.  I especially like the delicate vs. urban setting.  great contrast between the centered subject and her crude surroundings.  perfect DOF to mute the background autos and such...very nice 8</td>', 'nice capture.  I especially like the delicate vs. urban setting.  great contrast between the centered subject and her crude surroundings.  perfect DOF to mute the background autos and such...very nice 8', '2009-11-20 17:31:45.000000', NULL, 1),
