INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5736025, 834224, 96462, '<td valign="top">Nice water fall shot.  Really like the gentle water.  The rest of the shot, ie rocks and sky lack a bit of vibrance or energy, but I guess that was down to the weather!  7 from me.</td>', 'Nice water fall shot.  Really like the gentle water.  The rest of the shot, ie rocks and sky lack a bit of vibrance or energy, but I guess that was down to the weather!  7 from me.', '2009-11-21 15:36:11.000000', NULL, 1),
(5736028, 833775, 96462, '<td valign="top">Angelic.  But un-nerving!</td>', 'Angelic.  But un-nerving!', '2009-11-21 15:38:34.000000', NULL, 1),
(5736031, 834148, 96462, '<td valign="top">Don''t know how you took this under a basic edit, but very nice effect.  It''s the kind of thing I would have on my wall somewhere! 9 from me.</td>', 'Don''t know how you took this under a basic edit, but very nice effect.  It''s the kind of thing I would have on my wall somewhere! 9 from me.', '2009-11-21 15:40:22.000000', NULL, 1),
(5736032, 834287, 111808, '<td valign="top">The brilliant orange of the flower is echoed by the smaller ladybug within the centre. Just as the petals are opening outward so too is the shell of the insect as it prepares to fly away. The black background on this makes the main image pop &amp; is in turn echoed again by the small black spots on the shell. Very nice image, well composed &amp; thought out.</td>', 'The brilliant orange of the flower is echoed by the smaller ladybug within the centre. Just as the petals are opening outward so too is the shell of the insect as it prepares to fly away. The black background on this makes the main image pop & is in turn echoed again by the small black spots on the shell. Very nice image, well composed & thought out.', '2009-11-21 15:41:26.000000', NULL, 1),
(5736033, 833864, 96462, '<td valign="top">Lovely colours and contrast.  Top-notch. 9</td>', 'Lovely colours and contrast.  Top-notch. 9', '2009-11-21 15:41:30.000000', NULL, 1),
(5736035, 833746, 96462, '<td valign="top">I like this shot.  Lovely old vintage feel.  My only slight reservation is that it''s more of a "middled" composition than a centered one.  This middling instead of centering is quite a common theme in the challenege so I don''t know how harsh to score.  Think I''ll go for a 7.  Very good.</td>', 'I like this shot.  Lovely old vintage feel.  My only slight reservation is that it''s more of a "middled" composition than a centered one.  This middling instead of centering is quite a common theme in the challenege so I don''t know how harsh to score.  Think I''ll go for a 7.  Very good.', '2009-11-21 15:44:14.000000', NULL, 1),
(5736036, 833864, 111808, '<td valign="top">This is gorgeous - the deep reds and the texture in the repeating patterns of the folds which both encompass and enclose. Superb photograph, a definite favourite.</td>', 'This is gorgeous - the deep reds and the texture in the repeating patterns of the folds which both encompass and enclose. Superb photograph, a definite favourite.', '2009-11-21 15:45:16.000000', NULL, 1),
(5736039, 834061, 111808, '<td valign="top">The tones in the sky are diverse and beautifully tinged with multiple shades of light. The title is very appropriate to the much smaller shadowed building as natural Heaven is much more vast than the manmade structure, an appropriate analogy perhaps on a greater scale.</td>', 'The tones in the sky are diverse and beautifully tinged with multiple shades of light. The title is very appropriate to the much smaller shadowed building as natural Heaven is much more vast than the manmade structure, an appropriate analogy perhaps on a greater scale.', '2009-11-21 15:50:15.000000', NULL, 1),
(5736040, 833712, 111808, '<td valign="top">Nice tones in the cut crystal carafe. The choice of black and white makes this glitter and it is balanced by the two glasses, which hint at a story of their own perhaps.</td>', 'Nice tones in the cut crystal carafe. The choice of black and white makes this glitter and it is balanced by the two glasses, which hint at a story of their own perhaps.', '2009-11-21 15:53:18.000000', NULL, 1),
(5736046, 834279, 111808, '<td valign="top">Sharp enough that each seperate seed which makes up the centre can be seen in detail, the eye is immediately drawn in. The contrasts of the green with the complementary red of the petals is very effective as is the repeating patterns and shapes of the golden yellow curls. Natural artistry displayed well,an excellent capture.</td>', 'Sharp enough that each seperate seed which makes up the centre can be seen in detail, the eye is immediately drawn in. The contrasts of the green with the complementary red of the petals is very effective as is the repeating patterns and shapes of the golden yellow curls. Natural artistry displayed well,an excellent capture.', '2009-11-21 15:57:31.000000', NULL, 1),
(5736052, 834277, 111808, '<td valign="top">The overlapping fold patterns of repeating and enclosing petals make this photograph delightful and give the eye pause to go over them again and again. Very nice glitter in the dew or raindrops as well.</td>', 'The overlapping fold patterns of repeating and enclosing petals make this photograph delightful and give the eye pause to go over them again and again. Very nice glitter in the dew or raindrops as well.', '2009-11-21 16:01:46.000000', NULL, 1),
(5736069, 833312, 111808, '<td valign="top">My monitor view inadvertently crops this with just the crystal chandelier and a hint of the archway which is very effective in your chosen black and white due to repeating patterns of the ceiling and the curves of the alcove contrasting with the whiter lightsource.  Scrolling down to see the rest of it became more distracting as it was a bit hard to discern all the darker details.</td>', 'My monitor view inadvertently crops this with just the crystal chandelier and a hint of the archway which is very effective in your chosen black and white due to repeating patterns of the ceiling and the curves of the alcove contrasting with the whiter lightsource.  Scrolling down to see the rest of it became more distracting as it was a bit hard to discern all the darker details.', '2009-11-21 16:11:35.000000', NULL, 1),
(5736078, 834282, 111808, '<td valign="top">Frank the Frog looks like a delightful and intelligent creature who could engage in a quite learned and interesting conversation on the state of the world. Whimsical &amp; fun photograph.</td>', 'Frank the Frog looks like a delightful and intelligent creature who could engage in a quite learned and interesting conversation on the state of the world. Whimsical & fun photograph.', '2009-11-21 16:16:39.000000', NULL, 1),
(5736083, 833713, 111808, '<td valign="top">White dog in white snow and yet artistically done and expertly shot so that he/she stands out very well from the background. The texture of the fur is clear and even the snowflakes on the nose are very evident and contrast nicely with the darker nose. Cold dog whose expression belies the acceptance of Nature. The falling snowflakes in the back are an additional nice touch.</td>', 'White dog in white snow and yet artistically done and expertly shot so that he/she stands out very well from the background. The texture of the fur is clear and even the snowflakes on the nose are very evident and contrast nicely with the darker nose. Cold dog whose expression belies the acceptance of Nature. The falling snowflakes in the back are an additional nice touch.', '2009-11-21 16:22:31.000000', NULL, 1),
(5736086, 834122, 111808, '<td valign="top">Curves which repeat in the feathers and on the branch the parrot is sitting on and greens are excellent. The red eye is a nice contrast point.</td>', 'Curves which repeat in the feathers and on the branch the parrot is sitting on and greens are excellent. The red eye is a nice contrast point.', '2009-11-21 16:26:56.000000', NULL, 1),
(5736091, 834178, 111808, '<td valign="top">Love the blue shades and colour tones &amp; light reflecting patterns on the glass whose base is in turn reflected. The white sweeping curve is picked up again in the stem, the bowel base and the right side arcs. Simple subject and beautifully captured.</td>', 'Love the blue shades and colour tones & light reflecting patterns on the glass whose base is in turn reflected. The white sweeping curve is picked up again in the stem, the bowel base and the right side arcs. Simple subject and beautifully captured.', '2009-11-21 16:31:58.000000', NULL, 1),
(5736093, 834041, 111808, '<td valign="top">A study in contrasts: White tulip against black background which makes it stand out and the pleasing diagonal curves from right to left which place this in the centre complemented with the yellow green of the stem and the medium green patterns of the solo supporting leaf structure which are edged with just a tiny tinge of reflected bloom. This has beautiful shapes as well.</td>', 'A study in contrasts: White tulip against black background which makes it stand out and the pleasing diagonal curves from right to left which place this in the centre complemented with the yellow green of the stem and the medium green patterns of the solo supporting leaf structure which are edged with just a tiny tinge of reflected bloom. This has beautiful shapes as well.', '2009-11-21 16:36:59.000000', NULL, 1),
(5736100, 834184, 111808, '<td valign="top">Nice tones and textures - Sophia''s fur patterns stand out nicely against the square patterned background and the bokeh echoes the light and shadow interplay on her face.</td>', 'Nice tones and textures - Sophia''s fur patterns stand out nicely against the square patterned background and the bokeh echoes the light and shadow interplay on her face.', '2009-11-21 16:41:09.000000', NULL, 1),
(5736114, 834088, 111808, '<td valign="top">The individual square panes of the windows are echoed by the larger squares of the abbey building and in turn are echoed by the squares of the sidewalk. This can also be said of the archways in the window and building. There is the predominant colour of the greys which are also reflected in the man''s hair and in his jacket collar. Great lines in this and great reinforcing patterns because of that harmony.</td>', 'The individual square panes of the windows are echoed by the larger squares of the abbey building and in turn are echoed by the squares of the sidewalk. This can also be said of the archways in the window and building. There is the predominant colour of the greys which are also reflected in the man''s hair and in his jacket collar. Great lines in this and great reinforcing patterns because of that harmony.', '2009-11-21 16:47:11.000000', NULL, 1),
(5736120, 834196, 111808, '<td valign="top">Nice capture - the tongue is a funny plus but your main subject is so sharp that you can see the patterns in the beautiful crown of antlers and the textures in his fur. It contrasts nicely with the reinforcing brown tones in the background and brush set off with just enough white so that the view goes straight to the centre. It even echoes the white on his underchin.</td>', 'Nice capture - the tongue is a funny plus but your main subject is so sharp that you can see the patterns in the beautiful crown of antlers and the textures in his fur. It contrasts nicely with the reinforcing brown tones in the background and brush set off with just enough white so that the view goes straight to the centre. It even echoes the white on his underchin.', '2009-11-21 16:53:19.000000', NULL, 1),
(5736125, 834149, 111808, '<td valign="top">Brown and white peeling skin Textures, subtle tones,pleasing colours, repeating shapes and the white garlic that one sees first in the very centre. Nice composition.</td>', 'Brown and white peeling skin Textures, subtle tones,pleasing colours, repeating shapes and the white garlic that one sees first in the very centre. Nice composition.', '2009-11-21 16:56:44.000000', NULL, 1),
